css:
body {
           font-family: Arial, Helvetica, sans-serif;
           margin: 0;
           padding: 0;
           background: #fff;
           color: #000;
       }
       .container {
           width: 100%;
           border: 1px solid #000;
           padding: 24px 32px;
           background: #fff;
       }
       .header {
           display: flex;
           justify-content: space-between;
           align-items: center;
           border-bottom: 2px solid #000;
           padding-bottom: 10px;
       }
       .header .logo {
           width: 100px;
           height: 100px;
           object-fit: contain;
       }
       .company-details {
           text-align: left;
       }
       .company-details h2 {
           margin: 0 0 5px 0;
           font-size: 22px;
           font-weight: bold;
       }
       .company-details p {
           margin: 2px 0;
           font-size: 14px;
       }
       .section {
           margin-top: 18px;
       }
       .section-title {
           font-weight: bold;
           font-size: 15px;
           margin-bottom: 4px;
       }
       .details-table, .product-table, .totals-table {
           width: 100%;
           border-collapse: collapse;
           margin-top: 8px;
       }
       .details-table td, .details-table th,
       .product-table td, .product-table th,
       .totals-table td, .totals-table th {
           border: 1px solid #000;
           padding: 6px 8px;
           font-size: 14px;
       }
       .details-table th {
           background: #f2f2f2;
           font-weight: bold;
       }
       .product-table th {
           background: #f2f2f2;
           font-weight: bold;
           text-align: center;
       }
       .product-table td {
           text-align: center;
       }
       .totals-table {
           margin-top: 0;
       }
       .totals-table td {
           text-align: right;
       }
       .totals-table .label {
           text-align: left;
       }
       .bank-details {
           margin-top: 18px;
           font-size: 14px;
       }
       .footer {
           margin-top: 30px;
           display: flex;
           justify-content: space-between;
           font-size: 14px;
       }
       .signatory {
           text-align: right;
       }
       .jurisdiction {
           text-align: center;
           font-weight: bold;
           margin-top: 10px;
       }
       .words {
           font-style: italic;
           font-size: 13px;
       }
       .small {
           font-size: 12px;
       }
